pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 fuzzTimestamp, uint256 fuzzDifficulty) public {
        vm.assume(fuzzTimestamp <= type(uint64).max);
        vm.assume(fuzzDifficulty <= type(uint256).max);
        vm.warp(fuzzTimestamp);
        vm.roll(fuzzDifficulty);

        address player = makeAddr("player");
        vm.deal(player, 20 ether);
        vm.prank(player);
        try c.play{value: 10}() { } catch { }

        uint256 currentPot = c.pot();
        assertTrue(currentPot == 0 || currentPot == 10);
    }
}
